import React from 'react';
import { motion } from 'framer-motion';

const DESCS = {
  Calm:     'Low volatility — stable conditions. Confidence boosted +5%.',
  Trending: 'Directional momentum detected. Confidence unchanged.',
  Volatile: 'High uncertainty. Confidence reduced -15% for safety.',
};

/* Semi-circle SVG gauge */
const RegimeGauge = ({ regime }) => {
  const color = regime === 'Calm' ? '#00e87a' : regime === 'Trending' ? '#00d2ff' : '#ff3b6b';
  const pct   = regime === 'Calm' ? 0.15 : regime === 'Trending' ? 0.5 : 0.87;
  const R = 68; const cx = 80; const cy = 76;
  const start = Math.PI;
  const ang   = start + pct * Math.PI;
  const x1 = cx + R * Math.cos(start); const y1 = cy + R * Math.sin(start);
  const x2 = cx + R * Math.cos(ang);   const y2 = cy + R * Math.sin(ang);
  const la = pct > 0.5 ? 1 : 0;

  return (
    <svg width="160" height="88" viewBox="0 0 160 88">
      <path
        d={`M ${cx - R} ${cy} A ${R} ${R} 0 0 1 ${cx + R} ${cy}`}
        fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="8" strokeLinecap="round"
      />
      <path
        d={`M ${x1} ${y1} A ${R} ${R} 0 ${la} 1 ${x2} ${y2}`}
        fill="none" stroke={color} strokeWidth="8" strokeLinecap="round"
        style={{ filter: `drop-shadow(0 0 8px ${color})` }}
      />
      <circle cx={x2} cy={y2} r="5" fill={color} style={{ filter: `drop-shadow(0 0 6px ${color})` }} />
      <text x={cx - R + 2} y={cy + 16} fill="#3a4558" fontSize="8" fontFamily="JetBrains Mono">CALM</text>
      <text x={cx - 12}    y={cy + 16} fill="#3a4558" fontSize="8" fontFamily="JetBrains Mono">TREND</text>
      <text x={cx + R - 34} y={cy + 16} fill="#3a4558" fontSize="8" fontFamily="JetBrains Mono">VOLAT</text>
    </svg>
  );
};

const RegimeCard = ({ regime }) => {
  if (!regime) return null;
  const name = regime.regime_name || 'Unknown';
  const cls  = `rn-${name.toLowerCase()}`;

  return (
    <motion.div
      className="card regime-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, delay: 0.18 }}
    >
      <div className="card-title">
        <div className="card-ico ico-a">📡</div>
        <span className="card-title-text">Market Regime</span>
      </div>

      <div className="regime-inner">
        <RegimeGauge regime={name} />
        <div className={`regime-name-text ${cls}`}>{name.toUpperCase()}</div>
        <div className="regime-desc-text">{DESCS[name] || ''}</div>
        <div className="regime-conf">
          Adj. confidence: <span>{((regime.adjusted_model_confidence || 0.7) * 100).toFixed(1)}%</span>
        </div>
      </div>
    </motion.div>
  );
};

export default RegimeCard;
